// --- Safe rule evaluator -----------------------------------------------------
// NOTE: docs/RULES_ENGINE.md proposes using `Function(...)` to eval the
// caller-supplied `rule` string. That is a remote-code-execution sink: a
// request body like {"rule":"process.env"} or
// {"rule":"require('child_process').execSync('...')"} would leak secrets or
// take over the host. We deliberately do NOT follow that "reference" and
// instead parse a small, side-effect-free expression grammar.
//
// Supported grammar (operates on `ctx` only — no access to `req`, globals,
// require, process, etc.):
//   expr    := or
//   or      := and ('||' and)*
//   and     := not ('&&' not)*
//   not     := '!'? cmp
//   cmp     := add (('==' | '!=' | '<=' | '>=' | '<' | '>') add)?
//   add     := mul (('+' | '-') mul)*
//   mul     := unary (('*' | '/' | '%') unary)*
//   unary   := '-'? primary
//   primary := number | string | bool | null | path | '(' expr ')'
//   path    := 'ctx' ('.' ident | '[' (number|string) ']')*
function evalRule(rule, context) {
  if (typeof rule !== 'string') throw new Error('rule must be a string');
  if (rule.length > 1000) throw new Error('rule too long');

  // Tokenize
  const tokens = [];
  let i = 0;
  const two = ['==', '!=', '<=', '>=', '&&', '||'];
  const one = '+-*/%<>!().[],';
  while (i < rule.length) {
    const c = rule[i];
    if (/\s/.test(c)) { i++; continue; }
    if (i + 1 < rule.length && two.includes(rule.slice(i, i + 2))) {
      tokens.push({ t: 'op', v: rule.slice(i, i + 2) }); i += 2; continue;
    }
    if (one.includes(c)) { tokens.push({ t: 'op', v: c }); i++; continue; }
    if (c === '"' || c === "'") {
      const q = c; let s = ''; i++;
      while (i < rule.length && rule[i] !== q) {
        if (rule[i] === '\\' && i + 1 < rule.length) { s += rule[i + 1]; i += 2; }
        else { s += rule[i++]; }
      }
      if (rule[i] !== q) throw new Error('unterminated string');
      i++; tokens.push({ t: 'str', v: s }); continue;
    }
    if (/[0-9]/.test(c)) {
      let n = ''; while (i < rule.length && /[0-9.]/.test(rule[i])) n += rule[i++];
      tokens.push({ t: 'num', v: Number(n) }); continue;
    }
    if (/[A-Za-z_]/.test(c)) {
      let id = ''; while (i < rule.length && /[A-Za-z0-9_]/.test(rule[i])) id += rule[i++];
      if (id === 'true' || id === 'false') tokens.push({ t: 'bool', v: id === 'true' });
      else if (id === 'null') tokens.push({ t: 'null' });
      else tokens.push({ t: 'id', v: id });
      continue;
    }
    throw new Error('unexpected char: ' + c);
  }

  let p = 0;
  const peek = () => tokens[p];
  const eat = (t, v) => {
    const tok = tokens[p];
    if (!tok || tok.t !== t || (v !== undefined && tok.v !== v)) return null;
    p++; return tok;
  };

  function parseOr() {
    let left = parseAnd();
    while (eat('op', '||')) { const r = parseAnd(); left = left || r; }
    return left;
  }
  function parseAnd() {
    let left = parseNot();
    while (eat('op', '&&')) { const r = parseNot(); left = left && r; }
    return left;
  }
  function parseNot() {
    if (eat('op', '!')) return !parseCmp();
    return parseCmp();
  }
  function parseCmp() {
    const left = parseAdd();
    for (const op of ['==', '!=', '<=', '>=', '<', '>']) {
      if (eat('op', op)) {
        const r = parseAdd();
        switch (op) {
          case '==': return left === r;
          case '!=': return left !== r;
          case '<':  return left <   r;
          case '<=': return left <=  r;
          case '>':  return left >   r;
          case '>=': return left >=  r;
        }
      }
    }
    return left;
  }
  function parseAdd() {
    let left = parseMul();
    while (true) {
      if (eat('op', '+')) left = left + parseMul();
      else if (eat('op', '-')) left = left - parseMul();
      else return left;
    }
  }
  function parseMul() {
    let left = parseUnary();
    while (true) {
      if (eat('op', '*')) left = left * parseUnary();
      else if (eat('op', '/')) left = left / parseUnary();
      else if (eat('op', '%')) left = left % parseUnary();
      else return left;
    }
  }
  function parseUnary() {
    if (eat('op', '-')) return -parseUnary();
    return parsePrimary();
  }
  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new Error('unexpected end of expression');
    if (tok.t === 'num')  { p++; return tok.v; }
    if (tok.t === 'str')  { p++; return tok.v; }
    if (tok.t === 'bool') { p++; return tok.v; }
    if (tok.t === 'null') { p++; return null; }
    if (eat('op', '(')) {
      const v = parseOr();
      if (!eat('op', ')')) throw new Error('expected )');
      return v;
    }
    if (tok.t === 'id') {
      if (tok.v !== 'ctx') throw new Error('unknown identifier: ' + tok.v);
      p++;
      let cur = context;
      while (true) {
        if (eat('op', '.')) {
          const id = eat('id');
          if (!id) throw new Error('expected property name');
          cur = cur == null ? undefined : cur[id.v];
        } else if (eat('op', '[')) {
          const k = tokens[p++];
          if (!k || (k.t !== 'str' && k.t !== 'num')) throw new Error('bad index');
          if (!eat('op', ']')) throw new Error('expected ]');
          cur = cur == null ? undefined : cur[k.v];
        } else break;
      }
      return cur;
    }
    throw new Error('unexpected token');
  }

  const result = parseOr();
  if (p !== tokens.length) throw new Error('trailing tokens');
  return result;
}

