// Simple application for agent to work on

const express = require('express');
const app = express();

app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Safe rule evaluator.
//
// NOTE: docs/RULES_ENGINE.md proposes using `Function(...)` to eval a
// caller-supplied string. That is remote code execution and is intentionally
// NOT implemented here. Instead, /check accepts a structured rule of the form:
//
//   { "op": "and" | "or", "rules": [ ...subrules ] }
//   { "op": "not", "rule": <subrule> }
//   { "op": "eq" | "ne" | "lt" | "lte" | "gt" | "gte",
//     "field": "dot.path.into.context", "value": <literal> }
//   { "op": "in", "field": "...", "value": [literal, ...] }
//
// Only these ops are allowed; `field` is resolved against `context` via a
// safe path walk that refuses to cross prototype/__proto__/constructor.

const ALLOWED_COMPARATORS = {
  eq:  (a, b) => a === b,
  ne:  (a, b) => a !== b,
  lt:  (a, b) => a <   b,
  lte: (a, b) => a <=  b,
  gt:  (a, b) => a >   b,
  gte: (a, b) => a >=  b,
  in:  (a, b) => Array.isArray(b) && b.includes(a),
};

const UNSAFE_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function getPath(obj, path) {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  let cur = obj;
  for (const key of path.split('.')) {
    if (cur == null || typeof cur !== 'object') return undefined;
    if (UNSAFE_KEYS.has(key)) return undefined;
    if (!Object.prototype.hasOwnProperty.call(cur, key)) return undefined;
    cur = cur[key];
  }
  return cur;
}

function evalRule(rule, context, depth = 0) {
  if (depth > 32) throw new Error('rule nested too deeply');
  if (!rule || typeof rule !== 'object') {
    throw new Error('rule must be an object');
  }
  const { op } = rule;

  if (op === 'and' || op === 'or') {
    if (!Array.isArray(rule.rules)) throw new Error(`${op} requires "rules" array`);
    const results = rule.rules.map(r => evalRule(r, context, depth + 1));
    return op === 'and' ? results.every(Boolean) : results.some(Boolean);
  }

  if (op === 'not') {
    return !evalRule(rule.rule, context, depth + 1);
  }

  if (Object.prototype.hasOwnProperty.call(ALLOWED_COMPARATORS, op)) {
    const lhs = getPath(context, rule.field);
    return ALLOWED_COMPARATORS[op](lhs, rule.value);
  }

  throw new Error(`unsupported op: ${op}`);
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (rule == null) return res.status(400).json({ error: 'missing "rule"' });
  if (context == null || typeof context !== 'object') {
    return res.status(400).json({ error: 'missing or invalid "context"' });
  }
  try {
    const result = evalRule(rule, context);
    res.json({ result: Boolean(result) });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

