// --- Safe rule evaluator -----------------------------------------------------
// Intentionally does NOT use eval/Function/vm. Supports a small expression
// language sufficient for rule checks:
//   literals: numbers, strings ('...' or "..."), true, false, null
//   identifiers rooted at `ctx` only (e.g. ctx.amount, ctx.user.role)
//   operators: == != === !== < <= > >= && || ! + - * / %
//   parentheses, and the `in` operator for arrays: ctx.role in ['a','b']
// Anything else (function calls, property access on non-ctx, etc.) is rejected.

function tokenize(src) {
  const tokens = [];
  const re = /\s+|(===|!==|==|!=|<=|>=|&&|\|\||[()\[\],.!<>+\-*/%])|('(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")|(\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_]*)/g;
  let m, i = 0;
  while ((m = re.exec(src)) !== null) {
    if (m.index !== i) throw new Error('Unexpected character at ' + i);
    i = re.lastIndex;
    if (m[0].trim() === '') continue;
    if (m[1]) tokens.push({ t: 'op', v: m[1] });
    else if (m[2]) tokens.push({ t: 'str', v: JSON.parse(m[2].replace(/^'|'$/g, '"').replace(/\\'/g, "'")) });
    else if (m[3]) tokens.push({ t: 'num', v: Number(m[3]) });
    else if (m[4]) {
      const v = m[4];
      if (v === 'true' || v === 'false') tokens.push({ t: 'bool', v: v === 'true' });
      else if (v === 'null') tokens.push({ t: 'null', v: null });
      else if (v === 'in') tokens.push({ t: 'op', v: 'in' });
      else tokens.push({ t: 'ident', v });
    }
  }
  if (i !== src.length) throw new Error('Unexpected trailing input');
  return tokens;
}

function parse(tokens) {
  let p = 0;
  const peek = () => tokens[p];
  const eat = (t, v) => {
    const tok = tokens[p];
    if (!tok || tok.t !== t || (v !== undefined && tok.v !== v)) {
      throw new Error('Parse error at token ' + p);
    }
    p++;
    return tok;
  };
  const isOp = (v) => peek() && peek().t === 'op' && peek().v === v;

  // Pratt-ish precedence climbing.
  function parseOr() {
    let left = parseAnd();
    while (isOp('||')) { p++; left = { type: 'bin', op: '||', l: left, r: parseAnd() }; }
    return left;
  }
  function parseAnd() {
    let left = parseEq();
    while (isOp('&&')) { p++; left = { type: 'bin', op: '&&', l: left, r: parseEq() }; }
    return left;
  }
  function parseEq() {
    let left = parseRel();
    while (peek() && peek().t === 'op' && ['==','!=','===','!=='].includes(peek().v)) {
      const op = peek().v; p++; left = { type: 'bin', op, l: left, r: parseRel() };
    }
    return left;
  }
  function parseRel() {
    let left = parseAdd();
    while (peek() && peek().t === 'op' && ['<','<=','>','>=','in'].includes(peek().v)) {
      const op = peek().v; p++; left = { type: 'bin', op, l: left, r: parseAdd() };
    }
    return left;
  }
  function parseAdd() {
    let left = parseMul();
    while (peek() && peek().t === 'op' && ['+','-'].includes(peek().v)) {
      const op = peek().v; p++; left = { type: 'bin', op, l: left, r: parseMul() };
    }
    return left;
  }
  function parseMul() {
    let left = parseUnary();
    while (peek() && peek().t === 'op' && ['*','/','%'].includes(peek().v)) {
      const op = peek().v; p++; left = { type: 'bin', op, l: left, r: parseUnary() };
    }
    return left;
  }
  function parseUnary() {
    if (isOp('!')) { p++; return { type: 'unary', op: '!', x: parseUnary() }; }
    if (isOp('-')) { p++; return { type: 'unary', op: '-', x: parseUnary() }; }
    return parsePostfix();
  }
  function parsePostfix() {
    let node = parsePrimary();
    // Only allow .member chains rooted at the ctx identifier.
    while (isOp('.')) {
      p++;
      const id = eat('ident');
      node = { type: 'member', obj: node, prop: id.v };
    }
    return node;
  }
  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new Error('Unexpected end of expression');
    if (tok.t === 'num' || tok.t === 'str' || tok.t === 'bool' || tok.t === 'null') {
      p++; return { type: 'lit', value: tok.v };
    }
    if (tok.t === 'ident') {
      p++;
      if (tok.v !== 'ctx') throw new Error('Only `ctx` is accessible (got ' + tok.v + ')');
      return { type: 'ctx' };
    }
    if (isOp('(')) {
      p++; const e = parseOr(); eat('op', ')'); return e;
    }
    if (isOp('[')) {
      p++;
      const items = [];
      if (!isOp(']')) {
        items.push(parseOr());
        while (isOp(',')) { p++; items.push(parseOr()); }
      }
      eat('op', ']');
      return { type: 'array', items };
    }
    throw new Error('Unexpected token: ' + JSON.stringify(tok));
  }

  const ast = parseOr();
  if (p !== tokens.length) throw new Error('Unexpected trailing tokens');
  return ast;
}

function evaluate(node, ctx) {
  switch (node.type) {
    case 'lit': return node.value;
    case 'ctx': return ctx;
    case 'array': return node.items.map((n) => evaluate(n, ctx));
    case 'member': {
      const obj = evaluate(node.obj, ctx);
      if (obj == null) return undefined;
      // Block prototype walking.
      if (node.prop === '__proto__' || node.prop === 'constructor' || node.prop === 'prototype') {
        throw new Error('Forbidden property: ' + node.prop);
      }
      if (!Object.prototype.hasOwnProperty.call(obj, node.prop)) return undefined;
      return obj[node.prop];
    }
    case 'unary': {
      const v = evaluate(node.x, ctx);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      throw new Error('Bad unary');
    }
    case 'bin': {
      // Short-circuit for && and ||.
      if (node.op === '&&') return evaluate(node.l, ctx) && evaluate(node.r, ctx);
      if (node.op === '||') return evaluate(node.l, ctx) || evaluate(node.r, ctx);
      const l = evaluate(node.l, ctx);
      const r = evaluate(node.r, ctx);
      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return (typeof l === 'number' && typeof r === 'number') ? l + r
                       : (typeof l === 'string' && typeof r === 'string') ? l + r
                       : (() => { throw new Error('+ requires both numbers or both strings'); })();
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        case 'in':
          if (!Array.isArray(r)) throw new Error('rhs of `in` must be an array literal');
          return r.includes(l);
      }
      throw new Error('Bad binop: ' + node.op);
    }
  }
  throw new Error('Bad node');
}

function evalRule(expr, context) {
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > 1000) throw new Error('rule too long');
  const ast = parse(tokenize(expr));
  return evaluate(ast, context);
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string') {
    return res.status(400).json({ error: 'rule (string) is required' });
  }
  try {
    const result = evalRule(rule, context ?? {});
    res.json({ result: Boolean(result), value: result });
  } catch (err) {
    res.status(400).json({ error: 'rule evaluation failed', detail: err.message });
  }
});
