      // defined on Object.prototype shenanigans by requiring the key to
      // actually exist on a plain-ish object.
      if (typeof obj !== 'object' && typeof obj !== 'string') {
        throw new Error('member access only allowed on objects/strings');
      }
      return obj[key];
    }

    case 'UnaryExpression': {
      if (!ALLOWED_UNARY.has(node.operator) || !node.prefix) {
        throw new Error(`unary operator not allowed: ${node.operator}`);
      }
      const v = evalNode(node.argument, ctx);
      switch (node.operator) {
        case '!': return !v;
        case '-': return -v;
        case '+': return +v;
      }
      return undefined;
    }

    case 'BinaryExpression': {
      if (!ALLOWED_BINARY.has(node.operator)) {
        throw new Error(`binary operator not allowed: ${node.operator}`);
