  function parseLogicalOr() {
    let left = parseLogicalAnd();
    skip();
    while (s.startsWith('||', i) || s.startsWith('??', i)) {
      const op = s.substr(i, 2); i += 2;
      const right = parseLogicalAnd();
      left = { type: 'LogicalExpression', operator: op, left, right };
      skip();
    }
    return left;
  }
