    let left = parseEquality();
    skip();
    while (s.startsWith('&&', i)) {
      i += 2;
      const right = parseEquality();
      left = { type: 'LogicalExpression', operator: '&&', left, right };
      skip();
    }
    return left;
  }
  function parseEquality() {
    let left = parseComparison();
    skip();
