//   expr    := or
//   or      := and ( '||' and )*
//   and     := not ( '&&' not )*
//   not     := '!' not | cmp
//   cmp     := add ( ('=='|'!='|'<='|'>='|'<'|'>') add )?
//   add     := mul ( ('+'|'-') mul )*
//   mul     := unary ( ('*'|'/'|'%') unary )*
//   unary   := '-' unary | primary
//   primary := number | string | bool | null | path | '(' expr ')'
//   path    := ident ( '.' ident | '[' (number|string) ']' )*
//
// Identifiers can only resolve against the provided `ctx` object. There is no
// access to globals, `require`, `process`, function calls, or property lookups
// on prototypes.
function evaluateRule(expr, ctx) {
  let i = 0;
  const s = String(expr);

  const skip = () => { while (i < s.length && /\s/.test(s[i])) i++; };
  const match = (tok) => {
    skip();
    if (s.startsWith(tok, i)) { i += tok.length; return true; }
    return false;
  };

  const parseExpr = () => parseOr();

  const parseOr = () => {
    let left = parseAnd();
    while (match('||')) { const right = parseAnd(); left = left || right; }
    return left;
  };
  const parseAnd = () => {
    let left = parseNot();
    while (match('&&')) { const right = parseNot(); left = left && right; }
    return left;
  };
  const parseNot = () => {
    if (match('!') && !s.startsWith('=', i)) return !parseNot();
    return parseCmp();
  };
  const parseCmp = () => {
    let left = parseAdd();
    skip();
    for (const op of ['==', '!=', '<=', '>=', '<', '>']) {
      if (s.startsWith(op, i)) {
        i += op.length;
        const right = parseAdd();
        switch (op) {
          case '==': return left === right;
          case '!=': return left !== right;
          case '<=': return left <= right;
          case '>=': return left >= right;
          case '<':  return left < right;
          case '>':  return left > right;
        }
      }
    }
    return left;
  };
  const parseAdd = () => {
    let left = parseMul();
    skip();
    while (i < s.length && (s[i] === '+' || s[i] === '-')) {
      const op = s[i++];
      const right = parseMul();
      left = op === '+' ? left + right : left - right;
      skip();
    }
    return left;
  };
  const parseMul = () => {
    let left = parseUnary();
    skip();
    while (i < s.length && (s[i] === '*' || s[i] === '/' || s[i] === '%')) {
      const op = s[i++];
      const right = parseUnary();
      left = op === '*' ? left * right : op === '/' ? left / right : left % right;
      skip();
    }
    return left;
  };
  const parseUnary = () => {
    skip();
    if (s[i] === '-') { i++; return -parseUnary(); }
    return parsePrimary();
  };
