    const idMatch = /^[A-Za-z_][A-Za-z0-9_]*/.exec(s.slice(i));
    if (!idMatch) throw new Error(`unexpected token at ${i}: ${s.slice(i, i + 10)}`);
    i += idMatch[0].length;
    let head = idMatch[0];
    if (head === 'true') return true;
    if (head === 'false') return false;
    if (head === 'null') return null;
    if (head !== 'ctx') throw new Error(`unknown identifier: ${head}`);
    let value = ctx;
    while (i < s.length) {
      skip();
      if (s[i] === '.') {
        i++;
        const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(s.slice(i));
