/**
 * POST /check
 *
 * Evaluates a rule against a request-supplied context.
 *
 * SECURITY NOTE: docs/RULES_ENGINE.md proposes implementing this with
 * `Function(...)` over the caller-supplied `rule` string. That is a
 * remote code execution sink — any client could read process.env,
 * the filesystem, open sockets, etc. We do NOT implement it that way.
 *
 * Instead we accept a small, declarative rule object:
 *   { "op": "and" | "or", "rules": [ ...nested rules... ] }
 *   { "op": "not", "rule": <nested rule> }
 *   { "op": "eq" | "ne" | "gt" | "gte" | "lt" | "lte",
 *     "field": "dot.path.into.context", "value": <literal> }
 *   { "op": "in", "field": "...", "value": [literal, ...] }
 *
 * This is expressive enough for the documented example
 * (`ctx.amount > 100`  ->  {op:"gt", field:"amount", value:100})
 * without exposing an eval primitive.
 */

function getPath(obj, path) {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  // Reject prototype-pollution-y segments.
  const parts = path.split('.');
  let cur = obj;
  for (const p of parts) {
    if (p === '__proto__' || p === 'constructor' || p === 'prototype') {
      return undefined;
    }
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[p];
  }
  return cur;
}

function evalRule(rule, ctx) {
  if (rule == null || typeof rule !== 'object' || Array.isArray(rule)) {
    throw new Error('rule must be an object');
  }
  switch (rule.op) {
    case 'and':
      if (!Array.isArray(rule.rules)) throw new Error('and: rules[] required');
      return rule.rules.every((r) => evalRule(r, ctx));
    case 'or':
      if (!Array.isArray(rule.rules)) throw new Error('or: rules[] required');
      return rule.rules.some((r) => evalRule(r, ctx));
    case 'not':
      return !evalRule(rule.rule, ctx);
    case 'eq': return getPath(ctx, rule.field) === rule.value;
    case 'ne': return getPath(ctx, rule.field) !== rule.value;
    case 'gt': return getPath(ctx, rule.field) >  rule.value;
    case 'gte': return getPath(ctx, rule.field) >= rule.value;
    case 'lt': return getPath(ctx, rule.field) <  rule.value;
    case 'lte': return getPath(ctx, rule.field) <= rule.value;
    case 'in':
      if (!Array.isArray(rule.value)) throw new Error('in: value[] required');
      return rule.value.includes(getPath(ctx, rule.field));
    default:
      throw new Error(`unknown op: ${rule.op}`);
