// ---------------------------------------------------------------------------
// POST /check — evaluate a rule expression against a request-supplied context.
//
// SECURITY NOTE:
// docs/RULES_ENGINE.md proposes implementing this with `new Function(expr)`,
// which is equivalent to `eval` on attacker-controlled input. That is a
// remote-code-execution sink (CWE-94): a caller could submit a `rule` such as
// `process.env` or `require('child_process').execSync('...')` and read every
// secret in the process or run arbitrary commands. We deliberately do NOT
// follow that part of the doc.
//
// Instead we ship a small, safe expression evaluator that covers the
// documented use case (`ctx.amount > 100` and similar boolean predicates)
// by parsing the expression into an AST with Node's built-in parser and
// walking only a whitelisted subset of node types. No function calls, no
// member access into globals, no assignment, no `this`, no identifiers
// other than `ctx`.
// ---------------------------------------------------------------------------

const vm = require('vm');

// Node types we are willing to evaluate. Anything else -> reject.
const ALLOWED_NODES = new Set([
  'Program', 'ExpressionStatement',
  'Literal', 'TemplateLiteral', 'TemplateElement',
  'Identifier',           // only the single allowed root identifier (`ctx`)
  'MemberExpression',     // only computed=false or computed with literal key
  'BinaryExpression',     // ==, ===, !=, !==, <, <=, >, >=, +, -, *, /, %
