const express = require('express');
const app = express();

app.use(express.json());

// Safe rule evaluator.
//
// NOTE: docs/RULES_ENGINE.md proposes using `new Function(...)` to evaluate
// caller-supplied rule strings. That is a remote-code-execution vulnerability
// (an attacker can read process.env, the filesystem, spawn processes, etc.)
// and is not implemented here. Instead we support a small, safe expression
// language that covers the documented use case (e.g. `ctx.amount > 100`):
//
//   - identifiers/paths: ctx.foo, ctx.foo.bar
//   - literals: numbers, single/double-quoted strings, true, false, null
//   - comparison: == != === !== < <= > >=
//   - logical: && || !
//   - parentheses
//
// If you need richer expressions, add a real parser (e.g. jsep + a vetted
// interpreter) — do NOT switch to `Function`/`eval`.

const TOKEN_RE = /\s*(?:(===|!==|==|!=|<=|>=|&&|\|\||[<>!()])|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(-?\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_.]*))/y;

function tokenize(expr) {
  const tokens = [];
  TOKEN_RE.lastIndex = 0;
  while (TOKEN_RE.lastIndex < expr.length) {
    const start = TOKEN_RE.lastIndex;
    const m = TOKEN_RE.exec(expr);
    if (!m || m.index !== start) {
      throw new Error(`Unexpected token at position ${start}`);
    }
    if (m[1]) tokens.push({ type: 'op', value: m[1] });
    else if (m[2]) tokens.push({ type: 'str', value: JSON.parse(m[2].replace(/^'|'$/g, '"')) });
    else if (m[3]) tokens.push({ type: 'num', value: Number(m[3]) });
    else if (m[4]) {
      const v = m[4];
      if (v === 'true') tokens.push({ type: 'bool', value: true });
      else if (v === 'false') tokens.push({ type: 'bool', value: false });
      else if (v === 'null') tokens.push({ type: 'null', value: null });
      else tokens.push({ type: 'ident', value: v });
    }
  }
  // strip trailing whitespace handling: ensure we consumed everything
  if (expr.slice(TOKEN_RE.lastIndex).trim() !== '') {
    throw new Error(`Unexpected trailing input: ${expr.slice(TOKEN_RE.lastIndex)}`);
  }
  return tokens;
}

function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const eat = (v) => {
    const t = tokens[i];
    if (!t || (v && t.value !== v)) throw new Error(`Expected ${v}, got ${t ? t.value : 'EOF'}`);
    i++;
    return t;
  };

  // Precedence climbing: || < && < equality < comparison < unary < primary
  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().value === '||') { eat(); const r = parseAnd(); left = { op: '||', l: left, r }; }
    return left;
  }
  function parseAnd() {
    let left = parseEq();
    while (peek() && peek().value === '&&') { eat(); const r = parseEq(); left = { op: '&&', l: left, r }; }
    return left;
  }
  function parseEq() {
    let left = parseCmp();
    while (peek() && ['==','!=','===','!=='].includes(peek().value)) {
      const op = eat().value; const r = parseCmp(); left = { op, l: left, r };
    }
    return left;
  }
  function parseCmp() {
    let left = parseUnary();
    while (peek() && ['<','<=','>','>='].includes(peek().value)) {
      const op = eat().value; const r = parseUnary(); left = { op, l: left, r };
    }
    return left;
  }
  function parseUnary() {
    if (peek() && peek().value === '!') { eat(); return { op: '!', r: parseUnary() }; }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error('Unexpected end of expression');
    if (t.value === '(') { eat('('); const e = parseOr(); eat(')'); return e; }
    if (t.type === 'num' || t.type === 'str' || t.type === 'bool' || t.type === 'null') {
      i++; return { lit: t.value };
    }
    if (t.type === 'ident') { i++; return { path: t.value.split('.') }; }
    throw new Error(`Unexpected token: ${t.value}`);
  }

  const ast = parseOr();
  if (i !== tokens.length) throw new Error(`Unexpected token: ${tokens[i].value}`);
  return ast;
}

function resolvePath(scope, parts) {
  let cur = scope;
  for (const p of parts) {
    if (cur == null) return undefined;
    // Block prototype-walking / dangerous keys.
    if (p === '__proto__' || p === 'constructor' || p === 'prototype') return undefined;
    cur = cur[p];
  }
  return cur;
}

function evaluate(node, scope) {
  if ('lit' in node) return node.lit;
  if ('path' in node) return resolvePath(scope, node.path);
  if (node.op === '!') return !evaluate(node.r, scope);
  if (node.op === '&&') return evaluate(node.l, scope) && evaluate(node.r, scope);
  if (node.op === '||') return evaluate(node.l, scope) || evaluate(node.r, scope);
  const a = evaluate(node.l, scope), b = evaluate(node.r, scope);
